package com.aadil.ecommerce.services;import com.aadil.ecommerce.UserRole;import com.aadil.ecommerce.entities.AdminInvitationEntity;import com.aadil.ecommerce.enums.AdminRequestStatus;import com.aadil.ecommerce.exceptions.*;import com.aadil.ecommerce.repositories.AdminRepository;import com.aadil.ecommerce.repositories.UserRepository;import com.aadil.ecommerce.security.InvitationCreations;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.LocalDateTime;@Service@RequiredArgsConstructorpublic class UserService {    private final UserRepository userRepository;    private final InvitationCreations invitationCreations;    private final AdminRepository adminRepository;    @Transactional    public String invitationAcceptance (String rawToken){        String hashedToken = invitationCreations.invitationHash(rawToken);        AdminInvitationEntity invitation = adminRepository.findByTokenHash(hashedToken).orElseThrow(()->new InvitationNotFoundException("Invitation has NOT found"));        if (!(invitation.getAdminRequestStatus() == AdminRequestStatus.PENDING)){            throw new InvalidInvitationException("Invitation doesn't have a PENDING request");        }        else if (invitation.getExpiresAt().isBefore(LocalDateTime.now())){            throw new InvitationExpiredException("Invitation has expired");        }        if (invitation.getUser() == null){            throw new UserNotFoundException("This User is NO longer exists");        }        if (invitation.getUser().getRole() == UserRole.ADMIN){            throw new UserAlreadyAnAdminException("This User is already an ADMIN");        }        invitation.setAdminRequestStatus(AdminRequestStatus.ACCEPTED);        invitation.getUser().setRole(UserRole.ADMIN);        userRepository.save(invitation.getUser());        adminRepository.save(invitation);    return "User has changed from USER to ADMIN successfully";    }}